    nodes: [
      { id: 'start', type: 'trigger', next: 'form1' },
      { id: 'form1', type: 'form', next: 'done', schema: { fields } },
      ...extraNodes,
      { id: 'done', type: 'end', result: 'ok' },
    ],
  };
}

